SELECT *, AVG(rating) OVER w_part AS rating_avg_2, DENSE_RANK() OVER w_part_2 AS rating_dense_rank, RANK() OVER w_running AS rating_rank, ROW_NUMBER() OVER w_recent AS row_seq FROM suppliers WINDOW w_part AS (PARTITION BY city ORDER BY rating, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW), w_part_2 AS (ORDER BY rating DESC), w_running AS (PARTITION BY city ORDER BY rating NULLS FIRST), w_recent AS (ORDER BY rating, id);
